insert into public.projects (id, slug, title, category, location, scale, area, year, client, scope, summary, cover, gallery, before_after, featured, status, created_at) values
  ('prj-001', 'nha-may-ma-kem-cong-ty-van-xuan', 'Nhà máy mạ kẽm Công ty Vạn Xuân', 'industrial', 'CCN Vạn Xuân, Tam Nông, Phú Thọ', 'Khung thép tiền chế · 6.500 m²', 6500, 2024, 'Công ty Vạn Xuân', array['Thiết kế', 'Thi công']::text[], 'Nhà máy mạ kẽm nhúng nóng với kết cấu khung thép tiền chế khẩu độ lớn, hệ thống thông gió và xử lý khí thải chuyên dụng.', 'https://images.unsplash.com/photo-1565008447742-97f6f38c985c?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1565008447742-97f6f38c985c?auto=format&fit=crop&w=1600&q=80']::text[], null, true, 'published', '2024-06-01T00:00:00.000Z'),
  ('prj-002', 'nha-may-cong-ty-che-tao-bom-hai-duong', 'Nhà máy Công ty Chế tạo Bơm Hải Dương', 'industrial', 'Đường Ngô Quyền, TP. Hải Dương', 'Nhà xưởng + nhà ăn · 4.200 m²', 4200, 2023, 'Công ty CP Chế tạo Bơm Hải Dương', array['Thiết kế', 'Thi công']::text[], 'Cải tạo, mở rộng nhà xưởng sản xuất và thiết kế – thi công hạng mục nhà ăn cho cán bộ công nhân viên.', 'https://images.unsplash.com/photo-1513828583688-c52646db42da?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1513828583688-c52646db42da?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2023-06-02T00:00:00.000Z'),
  ('prj-003', 'nha-xuong-san-xuat-cho-thue-xuan-phuong', 'Nhà xưởng sản xuất & cho thuê Xuân Phương', 'industrial', 'CCN Đan Phượng giai đoạn 2, Hà Nội', 'Cụm nhà xưởng · 8.000 m²', 8000, 2024, 'Công ty Xuân Phương', array['Thiết kế', 'Thi công']::text[], 'Cụm nhà xưởng tiêu chuẩn phục vụ sản xuất và cho thuê, tối ưu khẩu độ, chiếu sáng tự nhiên và phòng cháy chữa cháy.', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2024-06-03T00:00:00.000Z'),
  ('prj-004', 'nha-may-cong-ty-tnhh-anh-sang-tien-du', 'Nhà máy Công ty TNHH Ánh sáng Tiến Dư', 'industrial', 'Xã Bình Minh, Thanh Oai, Hà Nội', 'Nhà máy + văn phòng · 5.100 m²', 5100, 2023, 'Công ty TNHH Ánh sáng Tiến Dư', array['Thiết kế', 'Thi công']::text[], 'Thiết kế và thi công trọn gói nhà máy sản xuất thiết bị chiếu sáng cùng khối văn phòng điều hành.', 'https://images.unsplash.com/photo-1590496793929-36417d3117de?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1590496793929-36417d3117de?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2023-06-04T00:00:00.000Z'),
  ('prj-005', 'nha-may-san-xuat-thiet-bi-cong-nghiep-kintop', 'Nhà máy sản xuất thiết bị công nghiệp Kintop', 'industrial', 'KCN Lai Cách, Cẩm Giàng, Hải Dương', 'Nhà xưởng · 7.200 m²', 7200, 2025, 'Công ty Kintop', array['Thiết kế', 'Thi công']::text[], 'Nhà máy sản xuất thiết bị công nghiệp, kết cấu thép kết hợp bê tông cốt thép, cầu trục 10 tấn.', 'https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=1600&q=80']::text[], null, true, 'published', '2025-06-05T00:00:00.000Z'),
  ('prj-006', 'nha-may-nhom-kinh-cong-ty-cp-hcc', 'Nhà máy nhôm kính Công ty CP HCC', 'industrial', 'CCN Thanh Đa, Phúc Thọ, Hà Nội', 'Nhà xưởng · 5.600 m²', 5600, 2024, 'Công ty CP Nhôm kính HCC', array['Thiết kế', 'Thi công']::text[], 'Nhà máy gia công nhôm kính với dây chuyền khép kín, mặt bằng bố trí theo luồng sản xuất một chiều.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2024-06-06T00:00:00.000Z'),
  ('prj-007', 'showroom-o-to-vinfast-vinh-yen', 'Showroom ô tô VinFast Vĩnh Yên', 'industrial', 'TP. Vĩnh Yên, Vĩnh Phúc', 'Showroom 3S · 2.400 m²', 2400, 2023, 'Đại lý VinFast Vĩnh Yên', array['Thi công']::text[], 'Thi công showroom – xưởng dịch vụ theo bộ nhận diện tiêu chuẩn của thương hiệu.', 'https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2023-06-07T00:00:00.000Z'),
  ('prj-008', 'nha-may-ming-shin-hung-yen', 'Nhà máy MING SHIN Hưng Yên', 'industrial', 'Hưng Yên', 'Nhà xưởng · 9.000 m²', 9000, 2025, 'MING SHIN', array['Thi công', 'Giám sát']::text[], 'Nhà máy vốn FDI, thi công kết cấu thép khẩu độ lớn và hệ thống kỹ thuật MEP đồng bộ.', 'https://images.unsplash.com/photo-1517089596392-fb9a9033e05b?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1517089596392-fb9a9033e05b?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2025-06-08T00:00:00.000Z'),
  ('prj-009', 'biet-thu-dia-trung-hai', 'Biệt thự Địa Trung Hải', 'residential', 'Thanh Hóa', '3 tầng · 520 m² sàn', 520, 2024, null, array['Thiết kế', 'Thi công']::text[], 'Biệt thự phong cách Địa Trung Hải với mái ngói đỏ, vòm cong và sân vườn bao quanh.', 'https://images.unsplash.com/photo-1599809275671-b5942cabc7a2?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1599809275671-b5942cabc7a2?auto=format&fit=crop&w=1600&q=80']::text[], '{"render":"https://images.unsplash.com/photo-1599809275671-b5942cabc7a2?auto=format&fit=crop&w=1600&q=80","real":"https://images.unsplash.com/photo-1599809275671-b5942cabc7a2?auto=format&fit=crop&w=1600&q=80"}'::jsonb, true, 'published', '2024-06-09T00:00:00.000Z'),
  ('prj-010', 'biet-thu-mai-nhat', 'Biệt thự mái Nhật', 'residential', 'Hòa Bình', '2 tầng · 380 m² sàn', 380, 2023, null, array['Thiết kế', 'Thi công']::text[], 'Biệt thự nghỉ dưỡng mái Nhật, hòa vào cảnh quan đồi núi với vật liệu gỗ và đá tự nhiên.', 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1600&q=80']::text[], '{"render":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1600&q=80","real":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1600&q=80"}'::jsonb, true, 'published', '2023-06-10T00:00:00.000Z'),
  ('prj-011', 'biet-thu-kdt-thanh-pho-giao-luu', 'Biệt thự KĐT Thành phố Giao Lưu', 'residential', 'KĐT Thành phố Giao Lưu, Bắc Từ Liêm, Hà Nội', '4 tầng · 600 m² sàn', 600, 2024, null, array['Thiết kế', 'Thi công']::text[], 'Biệt thự hiện đại với mặt đứng kính lớn, giếng trời trung tâm và tầng hầm để xe.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80']::text[], '{"render":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80","real":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80"}'::jsonb, true, 'published', '2024-06-11T00:00:00.000Z'),
  ('prj-012', 'biet-thu-gia-dinh-hac-thanh', 'Biệt thự gia đình Hạc Thành', 'residential', 'Phường Hạc Thành, Thanh Hóa', '3 tầng · 450 m² sàn', 450, 2025, null, array['Thiết kế', 'Thi công']::text[], 'Biệt thự tân cổ điển cho gia đình ba thế hệ, công năng tách bạch và sân vườn riêng.', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2025-06-12T00:00:00.000Z'),
  ('prj-013', 'khach-san-song-hong', 'Khách sạn Sông Hồng', 'residential', 'Vĩnh Phúc', '9 tầng · 4.800 m² sàn', 4800, 2022, null, array['Thiết kế']::text[], 'Khách sạn 3 sao với sảnh đón thông tầng, nhà hàng và 60 phòng nghỉ.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2022-06-13T00:00:00.000Z'),
  ('prj-014', 'van-phong-7-tang-bach-dang', 'Văn phòng 7 tầng Bạch Đằng', 'residential', 'Phường Bạch Đằng, TP. Hạ Long', '7 tầng · 1.750 m² sàn', 1750, 2024, null, array['Thiết kế']::text[], 'Tòa văn phòng mặt tiền kính hướng biển, kết cấu khung BTCT kết hợp lam chắn nắng.', 'https://images.unsplash.com/photo-1487958449943-2429e8be8625?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1487958449943-2429e8be8625?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2024-06-14T00:00:00.000Z'),
  ('prj-015', 'truong-cao-dang-thuong-mai', 'Trường Cao đẳng Thương mại', 'residential', 'TP. Đà Nẵng', 'Khối giảng đường · 6.000 m² sàn', 6000, 2022, null, array['Thiết kế']::text[], 'Khối giảng đường và thư viện với hành lang thông gió tự nhiên phù hợp khí hậu miền Trung.', 'https://images.unsplash.com/photo-1523217582562-09d0def993a6?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1523217582562-09d0def993a6?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2022-06-15T00:00:00.000Z'),
  ('prj-016', 'ket-cau-thep-chung-cu-five-star-garden', 'Kết cấu thép chung cư Five Star Garden', 'residential', 'Số 2 Kim Giang, Hà Nội', 'Hạng mục kết cấu thép', 3000, 2025, null, array['Thiết kế', 'Thi công']::text[], 'Thiết kế và thi công hạng mục kết cấu thép cho tổ hợp chung cư cao tầng.', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2025-06-16T00:00:00.000Z'),
  ('prj-017', 'chung-cu-mini-thach-ban', 'Chung cư mini Thạch Bàn', 'residential', 'Thạch Bàn, Long Biên, Hà Nội', '8 tầng · 1.400 m² sàn', 1400, 2023, null, array['Thiết kế', 'Thi công']::text[], 'Chung cư mini 24 căn hộ, tối ưu diện tích cho thuê và hệ thống PCCC theo quy chuẩn mới.', 'https://images.unsplash.com/photo-1574362848149-11496d93a7c7?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1574362848149-11496d93a7c7?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2023-06-17T00:00:00.000Z'),
  ('prj-018', 'giam-sat-hoan-thien-vinhomes-vu-yen', 'Giám sát hoàn thiện Vinhomes Vũ Yên', 'residential', 'Vũ Yên, Hải Phòng', 'Biệt thự đảo', 900, 2026, null, array['Giám sát']::text[], 'Giám sát thi công hoàn thiện kiến trúc và nội thất các căn biệt thự tại Vinhomes Royal Island.', 'https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2026-06-18T00:00:00.000Z'),
  ('prj-019', 'noi-that-nha-pho-anh-manh', 'Nội thất nhà phố anh Mạnh', 'interior', 'TP. Bắc Giang', '4 tầng · 320 m² sàn', 320, 2025, null, array['Thiết kế', 'Sản xuất', 'Thi công']::text[], 'Nội thất hiện đại tông ấm, toàn bộ đồ gỗ sản xuất tại xưởng Anyhome theo kích thước riêng.', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=80', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80', 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1600&q=80']::text[], '{"render":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=80","real":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=80"}'::jsonb, true, 'published', '2025-06-19T00:00:00.000Z'),
  ('prj-020', 'nha-hang-cafe-2-tang-mang-den', 'Nhà hàng café 2 tầng Măng Đen', 'interior', 'Khu du lịch Măng Đen, Kon Tum', '2 tầng · 400 m² sàn', 400, 2024, null, array['Thiết kế', 'Thi công']::text[], 'Không gian café – nhà hàng giữa rừng thông, vật liệu gỗ thông và kính lớn đón sương.', 'https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2024-06-20T00:00:00.000Z'),
  ('prj-021', 'quan-cafe-3-tang-da-nang', 'Quán café 3 tầng Đà Nẵng', 'interior', 'TP. Đà Nẵng', '3 tầng · 360 m² sàn', 360, 2024, null, array['Thiết kế', 'Thi công']::text[], 'Café phong cách industrial – tropical, sân thượng mở và quầy bar trung tâm.', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1600&q=80']::text[], null, false, 'published', '2024-06-21T00:00:00.000Z'),
  ('prj-022', 'can-ho-cao-cap-phong-cach-japandi', 'Căn hộ cao cấp phong cách Japandi', 'interior', 'Hà Nội', 'Căn hộ · 135 m²', 135, 2026, null, array['Thiết kế', 'Sản xuất', 'Thi công']::text[], 'Căn hộ 3 phòng ngủ tối giản Japandi với gỗ sồi sáng màu và ánh sáng gián tiếp.', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80', array['https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80']::text[], '{"render":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80","real":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80"}'::jsonb, true, 'published', '2026-06-22T00:00:00.000Z')
insert into public.posts (id, slug, title, excerpt, content, cover, category, tags, author, status, published_at, updated_at) values
  ('post-001', 'design-and-build-giai-phap-tron-goi', 'Design & Build: vì sao chủ đầu tư nên chọn một đầu mối từ thiết kế đến thi công?', 'Mô hình tổng thầu Design & Build giúp hạn chế sai lệch giữa bản vẽ và thực tế, tối ưu chi phí và kiểm soát tiến độ.', '<p>Khi thiết kế và thi công do hai đơn vị khác nhau đảm nhận, chủ đầu tư thường phải tự xử lý những xung đột giữa bản vẽ và hiện trường.</p><h2>3 lợi ích cốt lõi</h2><ul><li><strong>Một đầu mối chịu trách nhiệm</strong> cho toàn bộ chất lượng.</li><li><strong>Dự toán sát thực tế</strong> ngay từ giai đoạn ý tưởng.</li><li><strong>Rút ngắn tiến độ</strong> nhờ triển khai song song thiết kế – sản xuất.</li></ul><blockquote>Anyhome – Thiết kế khác biệt, kiến tạo không gian giá trị.</blockquote>', 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1600&q=80', 'knowledge', array['Design & Build', 'Tư vấn']::text[], 'Phòng Thiết kế', 'published', '2026-08-12T02:00:00.000Z', '2026-08-12T02:00:00.000Z'),
  ('post-002', 'khoi-cong-nha-may-kintop', 'Khởi công nhà máy sản xuất thiết bị công nghiệp Kintop tại KCN Lai Cách', 'Anyhome chính thức triển khai thi công nhà xưởng 7.200 m² cho Công ty Kintop tại Cẩm Giàng, Hải Dương.', '<p>Sáng nay, Anyhome cùng chủ đầu tư tổ chức lễ khởi công nhà máy Kintop.</p><h2>Quy mô dự án</h2><p>Nhà xưởng kết cấu thép kết hợp bê tông cốt thép, trang bị cầu trục 10 tấn.</p>', 'https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=1600&q=80', 'construction-log', array['Công nghiệp', 'Khởi công']::text[], 'Ban Chỉ huy công trường', 'published', '2026-07-03T02:00:00.000Z', '2026-07-03T02:00:00.000Z'),
  ('post-003', 'xu-huong-noi-that-japandi-2026', 'Xu hướng nội thất Japandi 2026: tối giản, ấm áp và bền vững', 'Gỗ sáng màu, đường nét tối giản và ánh sáng gián tiếp — vì sao Japandi tiếp tục dẫn dắt nội thất căn hộ cao cấp.', '<p>Japandi là sự giao thoa giữa tinh thần wabi-sabi Nhật Bản và công năng Bắc Âu.</p>', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80', 'knowledge', array['Nội thất', 'Xu hướng']::text[], 'Studio Nội thất', 'published', '2026-05-20T02:00:00.000Z', '2026-05-20T02:00:00.000Z'),
  ('post-004', 'tuyen-dung-ky-su-giam-sat', 'Tuyển dụng Kỹ sư giám sát xây dựng (Hà Nội, Hải Phòng)', 'Anyhome mở rộng đội ngũ, tuyển 05 kỹ sư giám sát dân dụng và công nghiệp.', '<p>Bản nháp — đang hoàn thiện mô tả công việc.</p>', 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1600&q=80', 'recruitment', array['Tuyển dụng']::text[], 'Phòng Nhân sự', 'draft', null, '2026-09-28T02:00:00.000Z')
